set -euo pipefail; ADB=adb; SERIAL=$($ADB devices | awk 'NR>1 && $2=="device" {print $1; exit}'); OUT="$HOME/agent-workspace/repos/tracker/checkpoints/ui-p0-baseline-20260912"; mkdir -p "$OUT/dbtmp"; cleanup(){ rm -rf "$OUT/dbtmp"; $ADB -s "$SERIAL" shell monkey -p io.blueeye -c android.intent.category.LAUNCHER 1 >/dev/null 2>&1 || true; }; trap cleanup EXIT; $ADB -s "$SERIAL" shell am force-stop io.blueeye; sleep 1; FILES=$($ADB -s "$SERIAL" shell run-as io.blueeye sh -c 'ls -1 databases 2>/dev/null' | tr -d '\r'); test -n "$FILES"; printf '%s\n' "$FILES" | sed 's/.*/DB_ENTRY_PRESENT/' | sort | uniq -c; while IFS= read -r f; do test -n "$f" || continue; safe=$(printf '%s' "$f" | tr '/ ' '__'); $ADB -s "$SERIAL" exec-out run-as io.blueeye cat "databases/$f" > "$OUT/dbtmp/$safe" || true; done <<< "$FILES"; python3 - <<'PY'
from pathlib import Path
import sqlite3, hashlib
out=Path.home()/"agent-workspace/repos/tracker/checkpoints/ui-p0-baseline-20260912/dbtmp"
candidates=[]
for p in out.iterdir():
    try:
        head=p.read_bytes()[:16]
    except Exception:
        continue
    if head==b'SQLite format 3\x00': candidates.append(p)
print('SQLITE_CANDIDATE_COUNT',len(candidates))
if not candidates: raise SystemExit('No SQLite database candidate found')
chosen=None
for p in candidates:
    try:
        con=sqlite3.connect(f'file:{p}?mode=ro', uri=True)
        tables={r[0] for r in con.execute("select name from sqlite_master where type='table'")}
        if 'devices' in tables:
            chosen=(p,con,tables); break
        con.close()
    except Exception:
        pass
if chosen is None: raise SystemExit('No SQLite DB with devices table')
p,con,tables=chosen
total=con.execute('select count(*) from devices').fetchone()[0]
max_seen=con.execute('select max(lastSeenAt) from devices').fetchone()[0]
recent=con.execute('select count(*) from devices where lastSeenAt >= ?',((max_seen or 0)-180000,)).fetchone()[0] if max_seen is not None else 0
print('DEVICE_TOTAL',total)
print('DENSE_180S_WINDOW_AT_DATASET_TAIL',recent)
for t in ('signal_samples','signalSamples','signal_sample'):
    if t in tables:
        print('SIGNAL_SAMPLE_TOTAL',con.execute(f'select count(*) from {t}').fetchone()[0]); break
print('DB_TABLE_COUNT',len(tables))
print('DB_BASELINE_SHA256',hashlib.sha256(p.read_bytes()).hexdigest())
con.close()
PY
